var INSTRUCTIONS = `Vyybe turns ideas into on-brand marketing visuals (Instagram/LinkedIn carousels, posts, stories, YouTube thumbnails, ads, slides, banners).
Frames are HTML+Tailwind fragments rendered on a fixed canvas; Vyybe handles fonts, icons, brand tokens, rendering, checks, editing and export.
Always follow the "vyybe" skill workflow when creating or editing visuals. Typical flow: vyybe_status \u2192 (create_project with all frames | write_frames) \u2192 fix issues from the preview \u2192 open_studio.`;
process.on("uncaughtException", (e2) => console.error("[vyybe] uncaught", e2));
process.on("unhandledRejection", (e2) => console.error("[vyybe] unhandled", e2));
var server2 = new McpServer({ name: "vyybe", version: VERSION, title: "Vyybe" }, { capabilities: { tools: {}, resources: {} }, instructions: INSTRUCTIONS });
await ensureServer().catch((e2) => console.error("[vyybe] bridge failed to start", e2));
registerTools(server2);
setHttpHandlers(() => appHandlers());
var transport = new StdioServerTransport();
await server2.connect(transport);
var stop = () => {
  shutdownChrome();
  process.exit(0);
};
process.stdin.on("close", stop);
process.on("SIGTERM", stop);
process.on("SIGINT", stop);
